mapper.select:
SELECT * FROM ( SELECT s.*, ROWNUM as rnum FROM ( SELECT a.*, c.name as categoryName, m.id as sellerName, NVL((SELECT max(bid_price) FROM bid_history b WHERE b.auction_seq = a.seq AND b.status = 0), 0) as highestBid, (SELECT max(bid_price) FROM bid_history WHERE auction_seq = a.seq AND member_seq = #{memberSeq}) as myBidPrice FROM auction a LEFT OUTER JOIN category c ON a.category_seq = c.seq INNER JOIN member m ON a.create_member_seq = m.seq
AND (a.name LIKE '%' || #{word} || '%' OR a.description LIKE '%' || #{word} || '%')
ORDER BY a.seq DESC ) s ) WHERE rnum BETWEEN #{begin} AND #{end}

    	SELECT * FROM (
	        SELECT * FROM bid_history 
	        WHERE auction_seq = #{seq} 
	          AND member_seq = #{memberSeq}
	        ORDER BY bid_time DESC
	    	)
	    WHERE rownum = 1

	SELECT count(*) 
    FROM auction 
    WHERE create_member_seq = #{memberSeq}

SELECT count(DISTINCT auction_seq) 
FROM bid_history 
WHERE member_seq = #{memberSeq}

mapper.update:
UPDATE point_lock
SET status = 2
WHERE auction_seq = #{auctionSeq}
  AND member_seq = #{winnerSeq}
  AND status = 0

UPDATE member
SET point = point - #{bidPrice}
WHERE seq = #{winnerSeq}

UPDATE member
SET point = point + #{bidPrice}
WHERE seq = #{sellerSeq}
